"use client";
import { useState, type ReactNode } from "react";

/**
 * Tur arama sonucu görseli: fotoğraf varsa turun fotoğrafını, yoksa (veya görsel
 * yüklenemezse) verilen ikonu (bayrağı) gösterir. Küçük listelerde yükü azaltmak
 * için önce hafif `-thumb` konversiyonu denenir, o başarısız olursa asıl `-high`
 * URL'ine düşülür.
 */
export default function TourThumb({
  image,
  alt,
  fallback,
  className,
}: {
  image?: string | null;
  alt: string;
  fallback: ReactNode;
  className?: string;
}) {
  const [triedHigh, setTriedHigh] = useState(false);
  const [failed, setFailed] = useState(false);

  if (!image || failed) return <>{fallback}</>;

  const src = triedHigh ? image : image.replace("-high.", "-thumb.");

  return (
    <img
      src={src}
      alt={alt}
      loading="lazy"
      className={className}
      onError={() => (triedHigh ? setFailed(true) : setTriedHigh(true))}
    />
  );
}
