import { apiClient } from "@/lib/apiClient";

/**
 * B2C kayıt — apiv3 `POST /auth/register` (app.token, tarayıcı → /api/apiv3 proxy).
 * Login ile AYNI kontrat: başarıda `{ token (Sanctum), token_old (api_token), user }`
 * döner; doğrulama hatalarında (422) apiClient `ApiError` fırlatır (`.errors` alan→mesaj).
 * Welcome credit + hoş geldin maili apiv3 tarafında işlenir.
 */

export type SignUpInput = {
    email: string;
    password: string;
    phone: string;
    firstName: string;
    lastName: string;
};

export type SignUpResult = {
    token: string;
    token_old: string;
    user: {
        id: number;
        email: string;
        name: string;
        avatar: string | null;
        roles: string[];
    };
};

export default function postSignUp({ requestData }: { requestData: SignUpInput }) {
    return apiClient<SignUpResult>("/auth/register", {
        method: "POST",
        body: {
            first_name: requestData.firstName,
            last_name: requestData.lastName,
            email: requestData.email,
            phone: requestData.phone,
            password: requestData.password,
        },
    });
}
