"use client";
import { useState, useEffect, useRef } from "react";
import { usePathname } from "next/navigation";
import { getCookie } from "cookies-next";
import { forceLogout } from "@/lib/authSession";
import Icon from "./icons";
import Placeholder from "./placeholder";
import AuthModal from "./auth-modal";
import MobileSearch from "./mobile-search";
import MobileDrawer from "./mobile-drawer";
import TourThumb from "./tour-thumb";
import { useSearch, popularDests } from "./use-search";
import { useWishlist } from "@/components/wishlist/wishlist-context";
import {
  DESTINATIONS,
  CATEGORIES,
  CONTINENT_TABS,
  CONTINENT_CITIES,
  CONTINENT_COUNTRIES,
  photoUrl,
  type Destination,
} from "./data";

type Mega = "cat" | "dest" | null;

export default function Header() {
  const [mega, setMega] = useState<Mega>(null);
  const [destTab, setDestTab] = useState("trending");
  const [searchOpen, setSearchOpen] = useState(false);
  const [mobileSearchOpen, setMobileSearchOpen] = useState(false);
  const [authOpen, setAuthOpen] = useState(false);
  const [drawerOpen, setDrawerOpen] = useState(false);
  const [userMenuOpen, setUserMenuOpen] = useState(false);
  const [userInitial, setUserInitial] = useState<string | null>(null);
  const [userName, setUserName] = useState("");
  const [userEmail, setUserEmail] = useState("");
  const [userChecked, setUserChecked] = useState(false);
  const closeTimer = useRef<ReturnType<typeof setTimeout> | null>(null);
  const searchRef = useRef<HTMLDivElement>(null);
  const userMenuRef = useRef<HTMLDivElement>(null);
  const mobileUserMenuRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const token = getCookie("auth-token");
    if (token) {
      const name = getCookie("user-full-name") as string | undefined;
      const email = getCookie("user-email") as string | undefined;
      setUserInitial(name ? name.trim().charAt(0).toUpperCase() : "U");
      setUserName(name ?? "");
      setUserEmail(email ?? "");
    }
    setUserChecked(true);
  }, []);

  useEffect(() => {
    if (!userMenuOpen) return;
    const handler = (e: MouseEvent) => {
      const t = e.target as Node;
      if (
        !userMenuRef.current?.contains(t) &&
        !mobileUserMenuRef.current?.contains(t)
      )
        setUserMenuOpen(false);
    };
    document.addEventListener("mousedown", handler);
    return () => document.removeEventListener("mousedown", handler);
  }, [userMenuOpen]);

  const handleLogout = () => {
    // Tüm auth cookie'lerini (auth-token-v3 dahil) silip sessizce reload eder.
    forceLogout();
  };

  const {
    q: searchQ,
    setQ: setSearchQ,
    clear: clearSearch,
    loading: searchLoading,
    results: searchResults,
  } = useSearch();
  const { count: wishlistCount, hydrated: wishlistHydrated } = useWishlist();

  const open = (which: Exclude<Mega, null>) => {
    if (closeTimer.current) clearTimeout(closeTimer.current);
    setMega(which);
    setSearchOpen(false);
  };
  const closeSoon = () => {
    if (closeTimer.current) clearTimeout(closeTimer.current);
    closeTimer.current = setTimeout(() => setMega(null), 120);
  };

  useEffect(() => {
    if (!searchOpen) return;
    const onDoc = (e: MouseEvent) => {
      if (searchRef.current && !searchRef.current.contains(e.target as Node))
        setSearchOpen(false);
    };
    document.addEventListener("mousedown", onDoc);
    return () => document.removeEventListener("mousedown", onDoc);
  }, [searchOpen]);

  const destCities = (CONTINENT_CITIES[destTab] || [])
    .map((id) => DESTINATIONS.find((d) => d.id === id))
    .filter(Boolean) as Destination[];

  // Tur detay sayfasında (/tour/[slug]) header sticky olmasın.
  const pathname = usePathname();
  const isStickyDisabled = pathname?.startsWith("/tour/") ?? false;
  // The home page hero has its own search box, so hide the header search there
  // (desktop + mobile) to avoid a confusing duplicate, like most large sites.
  const isHome = pathname === "/";

  return (
    <div
      onMouseLeave={closeSoon}
      className={
        (isStickyDisabled ? "tw-relative" : "tw-sticky tw-top-0") +
        " tw-z-50 tw-bg-white tsb-app-header"
      }
      style={{
        ["--tsb-gutter" as never]: "12px",
        borderBottom: "1px solid #ebe7f0",
        boxShadow:
          "0 1px 0 rgba(255,255,255,0.8), 0 2px 8px rgba(20,16,28,0.04)",
      }}
    >
      <style>{`
        @keyframes tsb-mega-in {
          from { opacity: 0; transform: translateY(-6px); }
          to { opacity: 1; transform: translateY(0); }
        }
        @keyframes tsb-pop-in {
          from { opacity: 0; transform: translateY(-4px); }
          to { opacity: 1; transform: translateY(0); }
        }
        .tsb-hdr-row { height: 64px; }
        @media (min-width: 721px) { .tsb-hdr-row { height: 84px; } }
        .tsb-logo { height: 48px; width: auto; display: block; }
        @media (min-width: 721px) { .tsb-logo { height: 52px; } }
      `}</style>

      <div
        className="tw-max-w-[1320px] tw-mx-auto tw-relative tw-grid tw-items-center tsb-hdr-row"
        style={{
          gridTemplateColumns: "auto 1fr auto",
          gap: "clamp(12px, 2vw, 28px)",
          paddingLeft: "var(--tsb-gutter)",
          paddingRight: "var(--tsb-gutter)",
        }}
      >
        {/* Brand */}
        <a
          href="/"
          aria-label="TravelShop Booking home"
          className="tw-flex tw-items-center tw-gap-2.5 tw-no-underline tw-text-[#14101c]"
          style={{ fontWeight: 800, letterSpacing: "-0.02em", fontSize: 19 }}
        >
          <img
            src="https://d2lpxiu1sq3srq.cloudfront.net/images/logo.svg"
            alt="TravelShop Booking"
            className="tsb-logo"
          />
        </a>

        {/* Centered search */}
        <div
          ref={searchRef}
          className={
            "tw-relative tw-w-full tw-justify-self-center max-[720px]:tw-hidden min-[1101px]:tw-max-w-[415px]" +
            (isHome ? " tw-hidden" : "")
          }
        >
          <div
            onClick={() => {
              setSearchOpen(true);
              setMega(null);
            }}
            className={
              "tw-flex tw-items-center tw-gap-2.5 tw-rounded-full tw-bg-white tw-px-4 tw-cursor-text tw-h-11 min-[1101px]:tw-h-12 tw-border-[1.5px] tw-border-solid tw-transition-[border-color,box-shadow] " +
              (searchOpen
                ? "tw-border-[#854ec9]"
                : "tw-border-[#d8d2e1] hover:tw-border-[#8a8398]")
            }
            style={searchOpen ? { boxShadow: "0 0 0 4px #f4eefb" } : undefined}
          >
            <span className="tw-text-[#854ec9] tw-flex-none">
              <Icon name="search" size={18} stroke={2} />
            </span>
            <input
              placeholder="Search tours, activities, or destinations…"
              value={searchQ}
              onFocus={() => {
                setSearchOpen(true);
                setMega(null);
              }}
              onChange={(e) => {
                setSearchQ(e.target.value);
                setSearchOpen(true);
                setMega(null);
              }}
              className="tw-flex-1 tw-min-w-0 tw-bg-transparent tw-border-0 tw-outline-none tw-text-[14px] tw-text-[#14101c] placeholder:tw-text-[#8a8398]"
            />
            {searchQ && (
              <button
                type="button"
                onClick={(e) => {
                  e.stopPropagation();
                  clearSearch();
                }}
                aria-label="Clear search"
                className="tw-w-[22px] tw-h-[22px] tw-rounded-full tw-grid tw-place-items-center tw-bg-[#f3f1f7] tw-text-[#5d556c] tw-border-0 tw-cursor-pointer tw-flex-none hover:tw-bg-[#14101c] hover:tw-text-white tw-transition-colors"
              >
                <Icon name="close" size={14} stroke={2.2} />
              </button>
            )}
          </div>

          {searchOpen && (
            <div
              className="tw-absolute tw-left-0 tw-right-0 tw-bg-white tw-border tw-border-solid tw-border-[#ebe7f0] tw-rounded-[16px] tw-py-2 tw-z-[48] tw-overflow-y-auto"
              style={{
                top: "calc(100% + 8px)",
                maxHeight: "70vh",
                boxShadow:
                  "0 18px 40px rgba(20, 16, 28, 0.14), 0 4px 10px rgba(20, 16, 28, 0.05)",
                animation: "tsb-pop-in 0.15s ease-out",
              }}
            >
              {!searchQ.trim() && (
                <>
                  <div className="tw-text-[11px] tw-font-bold tw-uppercase tw-tracking-[0.08em] tw-text-[#5d556c] tw-px-[18px] tw-pt-3 tw-pb-1.5">
                    Popular destinations
                  </div>
                  <div className="tw-grid tw-grid-cols-2">
                    {popularDests.map((d) => (
                      <a
                        key={d.id}
                        href={d.url}
                        onMouseDown={(e) => e.preventDefault()}
                        className="tw-flex tw-items-center tw-gap-3 tw-px-[18px] tw-py-2.5 tw-cursor-pointer tw-no-underline tw-text-[14px] tw-text-[#14101c] hover:tw-bg-[#faf9fc] tw-transition-colors"
                      >
                        <span className="tw-w-8 tw-h-8 tw-flex-none tw-rounded-full tw-grid tw-place-items-center tw-bg-[#f4eefb] tw-text-[#854ec9]">
                          <Icon name="pin" size={16} stroke={2} />
                        </span>
                        <span className="tw-flex tw-flex-col tw-leading-[1.3]">
                          <span className="tw-font-semibold tw-text-[14px]">
                            {d.city}
                          </span>
                          <span className="tw-text-[12px] tw-text-[#5d556c]">
                            {d.country}
                          </span>
                        </span>
                      </a>
                    ))}
                  </div>
                  <div className="tw-text-[11px] tw-font-bold tw-uppercase tw-tracking-[0.08em] tw-text-[#5d556c] tw-px-[18px] tw-pt-3 tw-pb-1.5">
                    Browse by category
                  </div>
                  <div className="tw-flex tw-flex-col">
                    {CATEGORIES.slice(0, 4).map((c) => (
                      <a
                        key={c.id}
                        href={c.url}
                        onMouseDown={(e) => e.preventDefault()}
                        className="tw-flex tw-items-center tw-gap-3 tw-px-[18px] tw-py-2.5 tw-cursor-pointer tw-no-underline tw-text-[14px] tw-text-[#14101c] hover:tw-bg-[#faf9fc] tw-transition-colors"
                      >
                        <span className="tw-w-8 tw-h-8 tw-flex-none tw-rounded-full tw-grid tw-place-items-center tw-bg-[#f4eefb] tw-text-[#854ec9]">
                          <Icon name={c.icon as never} size={16} stroke={2} />
                        </span>
                        <span className="tw-flex tw-flex-col tw-leading-[1.3]">
                          <span className="tw-font-semibold tw-text-[14px]">
                            {c.name}
                          </span>
                        </span>
                      </a>
                    ))}
                  </div>
                </>
              )}
              {searchLoading && (
                <div className="tw-flex tw-items-center tw-justify-center tw-gap-2 tw-py-5">
                  <span
                    className="tw-inline-block tw-h-4 tw-w-4 tw-animate-spin tw-rounded-full tw-border-2 tw-border-solid tw-border-[#854ec9] tw-border-r-transparent"
                    role="status"
                    aria-label="Loading"
                  />
                  <span className="tw-text-[13px] tw-text-[#5d556c]">
                    Searching...
                  </span>
                </div>
              )}
              {!searchLoading && searchResults && (
                <>
                  <div className="tw-flex tw-items-center tw-justify-between tw-px-[18px] tw-pt-3 tw-pb-1.5">
                    <span className="tw-text-[11px] tw-font-bold tw-uppercase tw-tracking-[0.08em] tw-text-[#5d556c]">
                      {searchResults.length > 0
                        ? `${searchResults.length} results`
                        : "No results"}
                    </span>
                    {searchResults.length > 0 && (
                      <a
                        href={"/search?term=" + encodeURIComponent(searchQ)}
                        onMouseDown={(e) => e.preventDefault()}
                        className="tw-text-[12px] tw-font-semibold tw-text-[#854ec9] tw-no-underline hover:tw-underline"
                      >
                        See all →
                      </a>
                    )}
                  </div>
                  <div className="tw-flex tw-flex-col">
                    {searchResults.length === 0 && (
                      <div className="tw-px-4 tw-py-4 tw-text-[13.5px] tw-text-[#5d556c]">
                        No results for &ldquo;{searchQ}&rdquo;.
                      </div>
                    )}
                    {searchResults.map((r) => {
                      const isDest = r.type !== "tour";
                      return (
                        <a
                          key={r.pageUrl}
                          href={"/" + r.pageUrl}
                          onMouseDown={(e) => e.preventDefault()}
                          className="tw-flex tw-items-center tw-gap-3 tw-px-[18px] tw-py-2.5 tw-cursor-pointer tw-no-underline tw-text-[14px] tw-text-[#14101c] hover:tw-bg-[#faf9fc] tw-transition-colors"
                        >
                          <span
                            className="tw-w-[28px] tw-h-[28px] tw-flex-none tw-rounded-[6px] tw-grid tw-place-items-center tw-overflow-hidden"
                            style={{ background: "rgba(133,78,201,0.1)" }}
                          >
                            {isDest ? (
                              <svg
                                width="13"
                                height="13"
                                viewBox="0 0 16 16"
                                fill="#ef4444"
                                xmlns="http://www.w3.org/2000/svg"
                              >
                                <path d="M8 16s6-5.686 6-10A6 6 0 0 0 2 6c0 4.314 6 10 6 10m0-7a3 3 0 1 1 0-6 3 3 0 0 1 0 6" />
                              </svg>
                            ) : (
                              <TourThumb
                                image={r.image}
                                alt={r.pageTitle}
                                className="tw-w-full tw-h-full tw-object-cover"
                                fallback={
                                  <svg
                                    width="13"
                                    height="13"
                                    viewBox="0 0 16 16"
                                    fill="#0063B1"
                                    xmlns="http://www.w3.org/2000/svg"
                                  >
                                    <path d="M14.778.085A.5.5 0 0 1 15 .5V8a.5.5 0 0 1-.314.464L14.5 8l.186.464-.003.001-.006.003-.023.009a12 12 0 0 1-.397.15c-.264.095-.631.223-1.047.35-.816.252-1.879.523-2.71.523-.847 0-1.548-.28-2.158-.525l-.028-.01C7.68 8.71 7.14 8.5 6.5 8.5c-.7 0-1.638.23-2.437.477A20 20 0 0 0 3 9.342V15.5a.5.5 0 0 1-1 0V.5a.5.5 0 0 1 1 0v.282c.226-.079.496-.17.79-.26C4.606.272 5.67 0 6.5 0c.84 0 1.524.277 2.121.519l.043.018C9.286.788 9.828 1 10.5 1c.7 0 1.638-.23 2.437-.477a20 20 0 0 0 1.349-.476l.019-.007.004-.002h.001" />
                                  </svg>
                                }
                              />
                            )}
                          </span>
                          <span className="tw-font-medium tw-text-[13.5px] tw-text-[#14101c]">
                            {r.pageTitle}
                          </span>
                        </a>
                      );
                    })}
                  </div>
                </>
              )}
            </div>
          )}
        </div>

        {/* Right cluster */}
        <div className="tw-flex tw-items-center tw-gap-4 tw-justify-self-end">
          {/* Primary nav (desktop only) */}
          <nav
            aria-label="Primary"
            className="tw-hidden min-[1101px]:tw-flex tw-items-center tw-gap-0.5"
          >


<a
  href="#"
  style={{ textDecoration: 'none' }}
  className="tw-relative tw-items-center tw-gap-1.5 tw-px-3 tw-py-2 tw-rounded-full tw-text-[15px] tw-font-semibold tw-text-[#2a2336] tw-bg-transparent tw-border-0 tw-cursor-pointer tw-whitespace-nowrap tw-leading-none"
>
  Hotels
</a>

            <button
              type="button"
              onMouseEnter={() => open("cat")}
              onFocus={() => open("cat")}
              className="tw-relative tw-inline-flex tw-items-center tw-gap-1.5 tw-px-3 tw-py-2 tw-rounded-full tw-text-[15px] tw-font-semibold tw-text-[#2a2336] tw-bg-transparent tw-border-0 tw-cursor-pointer tw-whitespace-nowrap tw-leading-none hover:tw-bg-[#f3f1f7]"
            >
              Things to do
              <span
                className="tw-text-[#8a8398]"
                style={{
                  display: "flex",
                  alignItems: "center",
                  transform: "translateY(2px)",
                }}
              >
                <Icon name="chevDown" size={16} stroke={2.2} />
              </span>
            </button>
            <button
              type="button"
              onMouseEnter={() => open("dest")}
              onFocus={() => open("dest")}
              className="tw-relative tw-inline-flex tw-items-center tw-gap-1.5 tw-px-3 tw-py-2 tw-rounded-full tw-text-[15px] tw-font-semibold tw-text-[#2a2336] tw-bg-transparent tw-border-0 tw-cursor-pointer tw-whitespace-nowrap tw-leading-none hover:tw-bg-[#f3f1f7]"
            >
              Destinations
              <span
                className="tw-text-[#8a8398]"
                style={{
                  display: "flex",
                  alignItems: "center",
                  transform: "translateY(2px)",
                }}
              >
                <Icon name="chevDown" size={16} stroke={2.2} />
              </span>
            </button>
            <a
              href="/deals"
              onMouseEnter={closeSoon}
              className="tw-inline-flex tw-items-center tw-gap-1.5 tw-px-3 tw-py-2 tw-rounded-full tw-text-[15px] tw-font-semibold tw-text-[#2a2336] tw-no-underline tw-whitespace-nowrap hover:tw-bg-[#f3f1f7]"
            >
              Deals
            </a>
          </nav>

          {/* Account (desktop only) */}
          <div className="tw-hidden min-[1101px]:tw-inline-flex tw-items-center tw-gap-1.5">
            <a
              href="/wishlist"
              aria-label="Wishlist"
              title="Wishlist"
              className="tw-relative tw-w-12 tw-h-12 tw-rounded-full tw-grid tw-place-items-center tw-bg-transparent tw-border-0 tw-cursor-pointer tw-text-[#2a2336] tw-no-underline hover:tw-bg-[#faf9fc] hover:tw-text-[#854ec9] tw-transition-colors"
            >
              <Icon name="heart" size={26} stroke={1.8} />
              {wishlistHydrated && wishlistCount > 0 && (
                <span
                  className="tw-absolute tw-grid tw-place-items-center tw-text-white tw-font-bold tw-px-1 tw-pointer-events-none"
                  style={{
                    top: 6,
                    right: 6,
                    minWidth: 18,
                    height: 18,
                    borderRadius: 9,
                    background: "#854ec9",
                    border: "2px solid #fff",
                    fontSize: 11,
                    lineHeight: 1,
                  }}
                >
                  {wishlistCount}
                </span>
              )}
            </a>
            {userInitial ? (
              <div
                ref={userMenuRef}
                className="tw-relative"
                style={{
                  opacity: userChecked ? 1 : 0,
                  transition: "opacity 0.25s ease",
                }}
              >
                <button
                  type="button"
                  onClick={() => setUserMenuOpen((v) => !v)}
                  className="tw-inline-flex tw-items-center tw-p-[4px] tw-rounded-full tw-bg-white tw-border tw-border-solid tw-border-[#854ec9] tw-cursor-pointer tw-transition-[border-color,box-shadow]"
                  style={
                    userMenuOpen
                      ? { boxShadow: "0 0 0 3px #f4eefb" }
                      : undefined
                  }
                >
                  <span
                    className="tw-w-9 tw-h-9 tw-rounded-full tw-grid tw-place-items-center tw-text-white tw-flex-none tw-font-bold tw-text-[16px]"
                    style={{ background: "#854ec9" }}
                  >
                    {userInitial}
                  </span>
                </button>
                {userMenuOpen && (
                  <div
                    className="tw-absolute tw-right-0 tw-bg-white tw-border tw-border-solid tw-border-[#ebe7f0] tw-rounded-[14px] tw-py-1.5 tw-z-[48] tw-w-[240px]"
                    style={{
                      top: "calc(100% + 10px)",
                      boxShadow:
                        "0 12px 32px rgba(20,16,28,0.12), 0 2px 8px rgba(20,16,28,0.06)",
                      animation: "tsb-pop-in 0.15s ease-out",
                    }}
                  >
                    <div
                      className="tw-px-4 tw-pt-2.5 tw-pb-2"
                      style={{ borderBottom: "1px solid #ebe7f0" }}
                    >
                      <p className="tw-m-0 tw-text-[14px] tw-font-semibold tw-text-[#14101c] tw-overflow-hidden tw-whitespace-nowrap tw-text-ellipsis">
                        {userName}
                      </p>
                      <p className="tw-m-0 tw-text-[12px] tw-text-[#5d556c] tw-overflow-hidden tw-whitespace-nowrap tw-text-ellipsis">
                        {userEmail}
                      </p>
                    </div>
                    <a
                      href="/profile"
                      className="tw-flex tw-items-center tw-gap-2.5 tw-px-4 tw-py-2.5 tw-text-[14px] tw-font-medium tw-text-[#14101c] tw-no-underline hover:tw-bg-[#faf9fc] tw-transition-colors"
                    >
                      <Icon name="user" size={16} stroke={1.8} />
                      My Profile
                    </a>
                    <a
                      href="/profile/bookings-enquiries"
                      className="tw-flex tw-items-center tw-gap-2.5 tw-px-4 tw-py-2.5 tw-text-[14px] tw-font-medium tw-text-[#14101c] tw-no-underline hover:tw-bg-[#faf9fc] tw-transition-colors"
                    >
                      <Icon name="calendar" size={16} stroke={1.8} />
                      Bookings &amp; Enquiries
                    </a>
                    <div
                      style={{
                        height: 1,
                        background: "#ebe7f0",
                        margin: "4px 0",
                      }}
                    />
                    <button
                      type="button"
                      onClick={handleLogout}
                      className="tw-w-full tw-flex tw-items-center tw-gap-2.5 tw-px-4 tw-py-2.5 tw-text-[14px] tw-font-medium tw-text-[#e53e3e] tw-bg-transparent tw-border-0 tw-cursor-pointer tw-text-left hover:tw-bg-[#fff5f5] tw-transition-colors"
                    >
                      <Icon name="arrowR" size={16} stroke={1.8} />
                      Log out
                    </button>
                  </div>
                )}
              </div>
            ) : (
              <button
                type="button"
                onClick={() => userChecked && setAuthOpen(true)}
                className="tw-inline-flex tw-items-center tw-p-[4px] tw-rounded-full tw-bg-white tw-border tw-border-solid tw-border-[#b0a8be] tw-cursor-pointer hover:tw-border-[#14101c] tw-transition-[border-color,box-shadow,opacity]"
                style={{ opacity: userChecked ? 1 : 0.35 }}
              >
                <span
                  className="tw-w-9 tw-h-9 tw-rounded-full tw-grid tw-place-items-center tw-text-white tw-flex-none"
                  style={{ background: "#3d3d3d" }}
                >
                  <Icon name="userSolid" size={20} stroke={0} />
                </span>
              </button>
            )}
          </div>

          {/* Mobile actions */}
          <div className="tw-inline-flex tw-items-center tw-gap-2 min-[1101px]:tw-hidden">
            {!isHome && (
              <button
                type="button"
                onClick={() => setMobileSearchOpen(true)}
                aria-label="Search"
                className="tw-relative tw-p-1 tw-rounded-full tw-grid tw-place-items-center tw-bg-transparent tw-border-0 tw-cursor-pointer tw-text-[#2a2336] hover:tw-bg-[#f3f1f7]"
              >
                <Icon name="search" size={24} stroke={2} />
              </button>
            )}
            <a
              href="/wishlist"
              aria-label="Wishlist"
              title="Wishlist"
              className="tw-relative tw-p-1 tw-rounded-full tw-grid tw-place-items-center tw-bg-transparent tw-border-0 tw-cursor-pointer tw-text-[#2a2336] tw-no-underline hover:tw-bg-[#f3f1f7]"
            >
              <Icon name="heart" size={22} stroke={2} />
              {wishlistHydrated && wishlistCount > 0 && (
                <span
                  className="tw-absolute tw-grid tw-place-items-center tw-text-white tw-font-bold tw-px-1 tw-leading-none"
                  style={{
                    top: -3,
                    right: -3,
                    minWidth: 16,
                    height: 16,
                    borderRadius: 999,
                    background: "#854ec9",
                    border: "1.5px solid #fff",
                    fontSize: 10,
                  }}
                >
                  {wishlistCount}
                </span>
              )}
            </a>
            {userInitial ? (
              <div
                className="tw-relative"
                ref={mobileUserMenuRef}
                style={{
                  opacity: userChecked ? 1 : 0,
                  transition: "opacity 0.25s ease",
                }}
              >
                <button
                  type="button"
                  onClick={() => setUserMenuOpen((v) => !v)}
                  aria-label="Account"
                  className="tw-inline-flex tw-items-center tw-p-[5px] tw-rounded-full tw-bg-white tw-border tw-border-solid tw-border-[#854ec9] tw-cursor-pointer tw-transition-[border-color,box-shadow]"
                  style={
                    userMenuOpen
                      ? { boxShadow: "0 0 0 3px #f4eefb" }
                      : undefined
                  }
                >
                  <span
                    className="tw-w-8 tw-h-8 tw-rounded-full tw-grid tw-place-items-center tw-text-white tw-flex-none tw-font-bold tw-text-[15px]"
                    style={{ background: "#854ec9" }}
                  >
                    {userInitial}
                  </span>
                </button>
                {userMenuOpen && (
                  <div
                    className="tw-absolute tw-right-0 tw-bg-white tw-border tw-border-solid tw-border-[#ebe7f0] tw-rounded-[14px] tw-py-1.5 tw-z-[48] tw-w-[240px]"
                    style={{
                      top: "calc(100% + 10px)",
                      boxShadow:
                        "0 12px 32px rgba(20,16,28,0.12), 0 2px 8px rgba(20,16,28,0.06)",
                      animation: "tsb-pop-in 0.15s ease-out",
                    }}
                  >
                    <div
                      className="tw-px-4 tw-pt-2.5 tw-pb-2"
                      style={{ borderBottom: "1px solid #ebe7f0" }}
                    >
                      <p className="tw-m-0 tw-text-[14px] tw-font-semibold tw-text-[#14101c] tw-overflow-hidden tw-whitespace-nowrap tw-text-ellipsis">
                        {userName}
                      </p>
                      <p className="tw-m-0 tw-text-[12px] tw-text-[#5d556c] tw-overflow-hidden tw-whitespace-nowrap tw-text-ellipsis">
                        {userEmail}
                      </p>
                    </div>
                    <a
                      href="/profile"
                      className="tw-flex tw-items-center tw-gap-2.5 tw-px-4 tw-py-2.5 tw-text-[14px] tw-font-medium tw-text-[#14101c] tw-no-underline hover:tw-bg-[#faf9fc] tw-transition-colors"
                    >
                      <Icon name="user" size={16} stroke={1.8} />
                      My Profile
                    </a>
                    <a
                      href="/profile/bookings-enquiries"
                      className="tw-flex tw-items-center tw-gap-2.5 tw-px-4 tw-py-2.5 tw-text-[14px] tw-font-medium tw-text-[#14101c] tw-no-underline hover:tw-bg-[#faf9fc] tw-transition-colors"
                    >
                      <Icon name="calendar" size={16} stroke={1.8} />
                      Bookings &amp; Enquiries
                    </a>
                    <div
                      style={{
                        height: 1,
                        background: "#ebe7f0",
                        margin: "4px 0",
                      }}
                    />
                    <button
                      type="button"
                      onClick={handleLogout}
                      className="tw-w-full tw-flex tw-items-center tw-gap-2.5 tw-px-4 tw-py-2.5 tw-text-[14px] tw-font-medium tw-text-[#e53e3e] tw-bg-transparent tw-border-0 tw-cursor-pointer tw-text-left hover:tw-bg-[#fff5f5] tw-transition-colors"
                    >
                      <Icon name="arrowR" size={16} stroke={1.8} />
                      Log out
                    </button>
                  </div>
                )}
              </div>
            ) : (
              <button
                type="button"
                onClick={() => userChecked && setAuthOpen(true)}
                aria-label="Sign in"
                className="tw-inline-flex tw-items-center tw-p-[5px] tw-rounded-full tw-bg-white tw-border tw-border-solid tw-border-[#b0a8be] tw-cursor-pointer hover:tw-border-[#14101c] tw-transition-[border-color,box-shadow,opacity]"
                style={{ opacity: userChecked ? 1 : 0.35 }}
              >
                <span
                  className="tw-w-8 tw-h-8 tw-rounded-full tw-grid tw-place-items-center tw-text-white tw-flex-none"
                  style={{ background: "#3d3d3d" }}
                >
                  <Icon name="userSolid" size={18} stroke={0} />
                </span>
              </button>
            )}
            <button
              type="button"
              onClick={() => setDrawerOpen(true)}
              aria-label="Menu"
              className="tw-relative tw-p-1 tw-rounded-full tw-grid tw-place-items-center tw-bg-transparent tw-border-0 tw-cursor-pointer tw-text-[#2a2336] hover:tw-bg-[#f3f1f7]"
            >
              <Icon name="menu" size={26} />
            </button>
          </div>
        </div>

        {/* Mega menu */}
        {mega && (
          <div
            className="tw-absolute tw-z-[49] tw-bg-white tw-border tw-border-solid tw-border-[#ebe7f0] tw-rounded-[20px] tw-overflow-hidden"
            style={{
              top: "calc(100% - 4px)",
              left: "var(--tsb-gutter)",
              right: "var(--tsb-gutter)",
              marginTop: 8,
              boxShadow:
                "0 24px 48px rgba(20, 16, 28, 0.14), 0 4px 12px rgba(20, 16, 28, 0.06)",
              animation: "tsb-mega-in 0.18s ease-out",
            }}
            onMouseEnter={() => open(mega)}
            onMouseLeave={closeSoon}
          >
            {mega === "cat" && (
              <div className="tw-grid" style={{ gridTemplateColumns: "1fr" }}>
                <div className="tw-px-8 tw-py-7">
                  <ul
                    className="tw-list-none tw-m-0 tw-p-0 tw-grid"
                    style={{
                      gridTemplateColumns: "repeat(4, 1fr)",
                      gap: "6px 20px",
                    }}
                  >
                    {CATEGORIES.map((c) => (
                      <li key={c.id}>
                        <a
                          href={c.url}
                          className="tw-group tw-flex tw-items-center tw-gap-3 tw-px-2.5 tw-py-2.5 tw--mx-2.5 tw-rounded-[10px] tw-no-underline tw-text-[14px] tw-text-[#2a2336] hover:tw-bg-[#faf9fc] hover:tw-text-[#854ec9] tw-transition-colors"
                        >
                          <span
                            className="tw-w-11 tw-h-11 tw-flex-none tw-rounded-[10px] tw-grid tw-place-items-center tw-overflow-hidden tw-border tw-border-solid tw-bg-[#faf9fc] tw-text-[#854ec9] tw-border-[#ebe7f0] group-hover:tw-border-[#854ec9] tw-transition-colors"
                            style={{ boxShadow: "none" }}
                          >
                            {c.photo ? (
                              <img
                                src={photoUrl(c.photo, 96) || ""}
                                alt=""
                                className="tw-w-full tw-h-full tw-object-cover tw-block"
                              />
                            ) : (
                              <Icon
                                name={c.icon as never}
                                size={18}
                                stroke={1.8}
                              />
                            )}
                          </span>
                          <span className="tw-flex tw-flex-col">
                            <span className="tw-block tw-font-semibold tw-text-[14px] tw-text-[#14101c] tw-leading-[1.2] group-hover:tw-text-[#854ec9] tw-transition-colors">
                              {c.name}
                            </span>
                            <span className="tw-block tw-text-[11.5px] tw-text-[#5d556c] tw-mt-0.5">
                              {c.count}
                            </span>
                          </span>
                        </a>
                      </li>
                    ))}
                  </ul>
                </div>
              </div>
            )}

            {mega === "dest" && (
              <div className="tw-flex tw-flex-col">
                <div
                  role="tablist"
                  className="tw-flex tw-gap-1"
                  style={{
                    padding: "14px 20px 0",
                    borderBottom: "1px solid #ebe7f0",
                  }}
                >
                  {CONTINENT_TABS.map((t) => {
                    const active = destTab === t.id;
                    return (
                      <button
                        key={t.id}
                        role="tab"
                        aria-selected={active}
                        onMouseEnter={() => setDestTab(t.id)}
                        onClick={() => setDestTab(t.id)}
                        className={
                          "tw-relative tw-inline-flex tw-items-center tw-gap-1.5 tw-bg-transparent tw-border-0 tw-cursor-pointer tw-whitespace-nowrap tw-text-[14px] tw-font-semibold tw-transition-colors " +
                          (active
                            ? "tw-text-[#854ec9]"
                            : "tw-text-[#5d556c] hover:tw-text-[#14101c]")
                        }
                        style={{
                          padding: "12px 16px 16px",
                          borderRadius: "8px 8px 0 0",
                        }}
                      >
                        <Icon name={t.icon as never} size={15} stroke={1.8} />
                        {t.label}
                        {active && (
                          <span
                            aria-hidden="true"
                            className="tw-absolute tw-bg-[#854ec9]"
                            style={{
                              left: 16,
                              right: 16,
                              bottom: -1,
                              height: 2,
                              borderRadius: "2px 2px 0 0",
                            }}
                          />
                        )}
                      </button>
                    );
                  })}
                </div>
                <div className="tw-px-7 tw-py-6">
                  <div className="tw-text-[11px] tw-font-bold tw-uppercase tw-tracking-[0.08em] tw-text-[#5d556c] tw-mb-3">
                    Popular countries
                  </div>
                  <div className="tw-flex tw-flex-wrap tw-gap-2 tw-mb-6">
                    {(CONTINENT_COUNTRIES[destTab] || []).map((c) => (
                      <a
                        key={c.name}
                        href={c.url}
                        className="tw-group tw-inline-flex tw-items-center tw-gap-2 tw-bg-white tw-border tw-border-solid tw-border-[#ebe7f0] tw-rounded-full tw-text-[13.5px] tw-font-semibold tw-text-[#14101c] tw-no-underline tw-cursor-pointer tw-whitespace-nowrap hover:tw-bg-[#faf9fc] hover:tw-border-[#854ec9] hover:tw-text-[#854ec9] tw-transition-colors"
                        style={{ padding: "8px 12px 8px 10px", lineHeight: 1 }}
                      >
                        <img
                          src={`/images/flags/${c.code}.png`}
                          srcSet={`/images/flags/${c.code}.png 2x`}
                          alt={c.name + " flag"}
                          loading="lazy"
                          className="tw-w-[22px] tw-h-4 tw-object-cover tw-rounded-[3px] tw-block tw-flex-none"
                          style={{ boxShadow: "0 0 0 1px rgba(20,16,28,0.08)" }}
                        />
                        <span className="tw-leading-none tw-inline-block">
                          {c.name}
                        </span>
                        {/* tour count — hidden until real data is wired
                        <span
                          className="tw-inline-flex tw-items-center tw-text-[11.5px] tw-font-semibold tw-text-[#5d556c] group-hover:tw-text-[#854ec9] tw-relative tw-pl-2 tw-transition-colors"
                          style={{ lineHeight: 1, fontVariantNumeric: "tabular-nums" }}
                        >
                          <span aria-hidden="true" className="tw-inline-block tw-w-px tw-h-3 tw-bg-[#ebe7f0] group-hover:tw-bg-[#c8b3e5] tw-mr-2 tw--ml-2 tw-transition-colors" />
                          {c.tours.toLocaleString('en-US')}
                        </span>
                        */}
                      </a>
                    ))}
                  </div>

                  <div className="tw-text-[11px] tw-font-bold tw-uppercase tw-tracking-[0.08em] tw-text-[#5d556c] tw-mb-3">
                    Popular cities
                  </div>
                  <div
                    className="tw-grid tw-mb-2"
                    style={{
                      gridTemplateColumns: "repeat(4, 1fr)",
                      gap: "4px 18px",
                    }}
                  >
                    {destCities.map((d) => (
                      <a
                        key={d.id}
                        href={d.url}
                        className="tw-group tw-flex tw-items-center tw-gap-3 tw-px-2.5 tw-py-2.5 tw-rounded-[10px] tw-no-underline tw-cursor-pointer hover:tw-bg-[#faf9fc] tw-transition-colors"
                      >
                        <span className="tw-w-12 tw-h-12 tw-flex-none tw-rounded-[10px] tw-overflow-hidden">
                          <Placeholder
                            tone={d.tone}
                            photo={d.photo}
                            alt={d.city}
                          />
                        </span>
                        <span>
                          <span className="tw-block tw-font-semibold tw-text-[14px] tw-text-[#14101c] group-hover:tw-text-[#854ec9] tw-transition-colors">
                            {d.city}
                          </span>
                          <span className="tw-block tw-text-[12px] tw-text-[#5d556c] tw-mt-0.5">
                            {d.country}
                          </span>
                        </span>
                      </a>
                    ))}
                  </div>

                  <div
                    className="tw-mt-[18px] tw-pt-4 tw-flex tw-justify-end"
                    style={{ borderTop: "1px solid #ebe7f0" }}
                  >
                    <a
                      href={
                        (
                          {
                            trending: "/worldwide-tours",
                            europe: "/europe-tours",
                            asia: "/asia-tours",
                            americas: "/north-america-tours",
                            mea: "/africa-tours",
                          } as Record<string, string>
                        )[destTab]
                      }
                      className="tw-inline-flex tw-items-center tw-gap-1.5 tw-text-[14px] tw-font-semibold tw-text-[#854ec9] tw-no-underline tw-whitespace-nowrap hover:tw-text-[#6a3da4]"
                    >
                      View all{" "}
                      {
                        (
                          {
                            trending: "worldwide",
                            europe: "Europe",
                            asia: "Asia",
                            americas: "America",
                            mea: "Africa",
                          } as Record<string, string>
                        )[destTab]
                      }{" "}
                      tours <span aria-hidden="true">→</span>
                    </a>
                  </div>
                </div>
              </div>
            )}
          </div>
        )}
      </div>

      <AuthModal open={authOpen} onClose={() => setAuthOpen(false)} />
      <MobileSearch
        open={mobileSearchOpen}
        onClose={() => setMobileSearchOpen(false)}
        q={searchQ}
        setQ={setSearchQ}
        clear={clearSearch}
        loading={searchLoading}
        popularDests={popularDests}
        results={searchResults}
      />
      <MobileDrawer open={drawerOpen} onClose={() => setDrawerOpen(false)} />
    </div>
  );
}
