import { photoUrl } from "./data";

const TONE_BG: Record<string, string> = {
  warm:   "#4a2a2e",
  sun:    "#3d3215",
  sea:    "#102b3b",
  forest: "#16302a",
  violet: "#2c1a45",
  rose:   "#3a1d33",
  amber:  "#3c2914",
  slate:  "#1f2536",
  brand:  "#432872",
};

interface PlaceholderProps {
  tone?: string;
  label?: string;
  photo?: string;
  alt?: string;
}

export default function Placeholder({ tone = "violet", label, photo, alt = "" }: PlaceholderProps) {
  const bg = TONE_BG[tone] || "#2a2336";
  const src = photo && photo.startsWith("http") ? photo : photoUrl(photo, 1200);
  return (
    <div
      className="tw-relative tw-w-full tw-h-full tw-overflow-hidden"
      style={{
        background: `repeating-linear-gradient(135deg, rgba(255,255,255,0.06) 0 12px, transparent 12px 24px), ${bg}`,
      }}
    >
      {src && (
        <img
          src={src}
          alt={alt}
          loading="lazy"
          className="tw-absolute tw-inset-0 tw-w-full tw-h-full tw-object-cover tw-block"
          onError={(e) => { (e.currentTarget as HTMLImageElement).style.display = "none"; }}
        />
      )}
      {label && !photo && (
        <span
          className="tw-absolute tw-top-[10px] tw-left-[10px] tw-z-[1] tw-uppercase tw-tracking-wider tw-rounded-[4px] tw-px-[6px] tw-py-[3px]"
          style={{
            fontFamily: '"JetBrains Mono", ui-monospace, SFMono-Regular, Menlo, monospace',
            fontSize: 10,
            color: "rgba(255,255,255,0.55)",
            background: "rgba(0,0,0,0.25)",
            letterSpacing: "0.06em",
          }}
        >
          {label}
        </span>
      )}
    </div>
  );
}
