"use client";
import {
  createContext,
  useContext,
  useEffect,
  useState,
  useCallback,
  type ReactNode,
} from "react";

const STORAGE_KEY = "tsb-wishlist";

export type WishlistItem = {
  id: number | string;
  slug: string;
  name: string;
  image?: string;
  /** ISO timestamp of when it was added — used to sort the wishlist page */
  addedAt?: string;
};

type WishlistContextValue = {
  items: WishlistItem[];
  count: number;
  /** true once localStorage has been read on the client (avoids SSR mismatch) */
  hydrated: boolean;
  isFavorite: (id: WishlistItem["id"]) => boolean;
  toggle: (item: WishlistItem) => void;
  add: (item: WishlistItem) => void;
  remove: (id: WishlistItem["id"]) => void;
  clear: () => void;
};

const WishlistContext = createContext<WishlistContextValue | null>(null);

function readStorage(): WishlistItem[] {
  if (typeof window === "undefined") return [];
  try {
    const raw = window.localStorage.getItem(STORAGE_KEY);
    if (!raw) return [];
    const parsed = JSON.parse(raw);
    if (!Array.isArray(parsed)) return [];
    // keep only well-formed entries
    return parsed.filter(
      (x): x is WishlistItem =>
        x && (typeof x.id === "number" || typeof x.id === "string") && !!x.slug
    );
  } catch {
    return [];
  }
}

export function WishlistProvider({ children }: { children: ReactNode }) {
  const [items, setItems] = useState<WishlistItem[]>([]);
  const [hydrated, setHydrated] = useState(false);

  // Load once on mount.
  useEffect(() => {
    setItems(readStorage());
    setHydrated(true);
  }, []);

  // Persist + keep other tabs in sync.
  useEffect(() => {
    if (!hydrated) return;
    try {
      window.localStorage.setItem(STORAGE_KEY, JSON.stringify(items));
    } catch {
      /* storage full / unavailable — ignore */
    }
  }, [items, hydrated]);

  useEffect(() => {
    const onStorage = (e: StorageEvent) => {
      if (e.key === STORAGE_KEY) setItems(readStorage());
    };
    window.addEventListener("storage", onStorage);
    return () => window.removeEventListener("storage", onStorage);
  }, []);

  const isFavorite = useCallback(
    (id: WishlistItem["id"]) => items.some((x) => x.id === id),
    [items]
  );

  const add = useCallback((item: WishlistItem) => {
    setItems((prev) =>
      prev.some((x) => x.id === item.id)
        ? prev
        : [{ ...item, addedAt: new Date().toISOString() }, ...prev]
    );
  }, []);

  const remove = useCallback((id: WishlistItem["id"]) => {
    setItems((prev) => prev.filter((x) => x.id !== id));
  }, []);

  const toggle = useCallback((item: WishlistItem) => {
    setItems((prev) =>
      prev.some((x) => x.id === item.id)
        ? prev.filter((x) => x.id !== item.id)
        : [{ ...item, addedAt: new Date().toISOString() }, ...prev]
    );
  }, []);

  const clear = useCallback(() => setItems([]), []);

  return (
    <WishlistContext.Provider
      value={{
        items,
        count: items.length,
        hydrated,
        isFavorite,
        toggle,
        add,
        remove,
        clear,
      }}
    >
      {children}
    </WishlistContext.Provider>
  );
}

export function useWishlist() {
  const ctx = useContext(WishlistContext);
  if (!ctx)
    throw new Error("useWishlist must be used within a WishlistProvider");
  return ctx;
}
