import { apiClient } from "@/lib/apiClient";

/**
 * Şifre sıfırlama linki iste — apiv3 `POST /auth/forgot-password` (app.token,
 * tarayıcı → /api/apiv3 proxy). Yanıt gövdesi tüketici tarafından okunmaz;
 * istek başarıyla tamamlanması (resolve) yeterlidir.
 */
export default function postResetPassword({ email }: { email: string }) {
    return apiClient("/auth/forgot-password", {
        method: "POST",
        body: { email },
    });
}
