"use client";

import { useEffect, useRef } from "react";

/**
 * `?ref=KOD` ile gelen ziyaretçinin tıklamasını apiv3'e bildirir ve dönen `click_uid`'i
 * saklar. Kök layout'ta mount edilir, hiçbir şey render etmez.
 *
 * Neden client-side (middleware değil): site ağırlıklı olarak statik render edilip
 * Cloudflare edge'inden servis ediliyor — istek çoğu zaman origin'e hiç ulaşmadığı için
 * sunucu tarafında cookie yazılamaz. Client-side yakalama cache davranışından bağımsızdır.
 *
 * `useSearchParams` BİLEREK kullanılmıyor: App Router'da statik üretimden çıkmaya
 * (client-side render) yol açar ve ~13k tur sayfasının statik render'ını bozardı.
 * URL doğrudan window üzerinden, effect içinde okunuyor.
 */
export default function AffiliateTracker() {
    const handled = useRef(false);

    useEffect(() => {
        // React strict mode çift mount'ta ikinci kez tıklama yazmasın.
        if (handled.current) return;
        handled.current = true;

        const url = new URL(window.location.href);
        const ref = url.searchParams.get("ref");

        if (!ref) return;

        const campaign = url.searchParams.get("c");
        const subId = url.searchParams.get("sid");

        // Takip parametrelerini adres çubuğundan temizle: canonical/paylaşım kirliliğini
        // ve her affiliate kodunun ayrı bir edge cache girdisi üretmesini önler.
        ["ref", "c", "sid"].forEach((key) => url.searchParams.delete(key));
        window.history.replaceState({}, "", url.pathname + url.search + url.hash);

        (async () => {
            try {
                // Dinamik import: ?ref= YOKSA (yani isteklerin neredeyse tamamında) apiClient
                // ve cookies-next kök layout paketine hiç girmez. Ziyaretçi bedel ödemez.
                const [{ apiClient }, { storeAttributionToken }] = await Promise.all([
                    import("@/lib/apiClient"),
                    import("@/lib/affiliateTracking"),
                ]);

                const res = await apiClient<{ click_uid: string | null; expires_at: string | null }>(
                    "/affiliate/click",
                    {
                        method: "POST",
                        body: {
                            ref,
                            path: url.pathname,
                            campaign: campaign || undefined,
                            sub_id: subId || undefined,
                            referer: document.referrer || undefined,
                        },
                    }
                );

                // Kod geçersizse apiv3 click_uid: null döner — sessizce hiçbir şey yapma.
                if (res?.click_uid) {
                    storeAttributionToken(res.click_uid, res.expires_at);
                }
            } catch {
                // Takip asla ziyaretçinin akışını bozmamalı.
            }
        })();
    }, []);

    return null;
}
